 private static void flat(JsonElement expected,PanelCornerGeometry.FlatCorner corner){if(expected==null||expected.isJsonNull()){need(corner==null,"flat contact absent");return;}need(corner!=null,"flat contact present");var a=expected.getAsJsonArray();Object[] values={corner.frontArm,corner.backArm,corner.frontRight,corner.backRight,corner.straightLeft,corner.straightRight,corner.left(),corner.right()};for(int i=0;i<values.length;i++)equal(a.get(i),values[i]);}
